# -*- coding: utf-8 -*-
from author_common import *
def mc(doc,page,prompt,correct,b,c,e,why,level='understand'):
    add(doc,page,'single_choice',prompt,'a',why,[correct,b,c,e]);q=qs[-1];q['id']=f'{doc}-x{sum(x["topic"]==doc for x in qs):02}';q['author_id']='question-engineer-b';q['cognitive_level']=level
d='p2-t3-d03'
mc(d,10,'Chunk gốc đã mất bảng và quan hệ ngữ cảnh lúc ingestion. Vì sao chỉ đổi retriever thường chưa đủ?','Retrieval bị giới hạn bởi nội dung đã được index','Retriever mạnh luôn tự khôi phục mọi thông tin chưa index','Reranker có thể sinh lại bảng nguồn chính xác mà không cần dữ liệu','Generation prompt đủ để phục hồi mọi cấu trúc đã mất','Ingestion đặt trần chất lượng; thiếu thông tin/cấu trúc ở index không thể được giải quyết chỉ bằng lấy lại cùng nội dung.','analyze')
mc(d,52,'Chunk chứa đáp án không có trong candidate retrieval. Vì sao chỉ thêm reranker chưa xử lý được lỗi này?','Reranker chỉ sắp lại candidate đã lấy, không phục hồi chunk bị miss','Reranker luôn tự tìm toàn corpus nên chắc chắn lấy được chunk thiếu','Cross-encoder sẽ sinh chunk mới để lấp corpus trống','Chỉ cần giảm top-k xuống1để recall tự tăng','Reranking có ROI khi recall đã đủ; nếu chunk đúng chưa được retrieve thì phải sửa retrieval trước khi ranking candidate.','analyze')
mc(d,15,'RAPTOR hỗ trợ câu hỏi tổng hợp xuyên nhiều đoạn bằng cấu trúc gì?','Cây tóm tắt phân cấp, truy xuất ở độ cao phù hợp','Chỉ một flat index các chunk cùng mức chi tiết','Chỉ tăng overlap mà không có summary node','Chỉ rerank một chunk ngắn nhất cho mọi câu hỏi','RAPTOR cluster và tóm tắt đệ quy; câu hỏi tổng quan dùng node cao, chi tiết dùng leaf, đổi thêm chi phí index.')
mc(d,17,'Contextual enrichment khác late chunking ở chi phí bổ sung chủ yếu nào?','Gọi LLM tạo ngữ cảnh cho chunk ở thời điểm index','Luôn gọi LLM cho mỗi user query thay index','Không dùng văn bản context nào trước embed','Chỉ thay số dimension mà không tạo ngữ cảnh','Contextual prepend dùng LLM thêm câu ngữ cảnh, thường một call/chunk offline; late chunking dùng encoder phù hợp rồi pooling.')
mc(d,19,'Hypothetical Q&A ở ingestion làm giảm vocab gap bằng cách nào?','Index câu hỏi giả định trỏ về chunk để query user khớp trực tiếp dạng câu hỏi','Chỉ thay câu trả lời thật bằng đáp án giả để generate','Sinh câu hỏi sau mọi user query và không lưu index','Chỉ lập mục lục tên tài liệu mà không embedding','User hay hỏi khác cách văn bản khẳng định; các câu hỏi chunk trả lời được được embed cạnh chunk để làm cầu nối.')
mc(d,20,'Matryoshka representation cho phép một embedding phục vụ nhiều budget ra sao?','Dùng prefix số chiều ngắn để lọc thô rồi full vector cho bước tinh','Cắt tùy vị trí dimension của bất kỳ model thường mà không mất chất lượng','Bắt buộc re-embed toàn corpus mỗi lần thay dimension budget','Dùng cùng vector nhưng thêm zero để luôn tăng precision','Model MRL được train cho vector lồng nhau; truncate prefix tạo trade-off cost/quality mà không cần gọi embed lại.')
mc(d,21,'Một PDF scan nhiều bảng cần chọn ingestion theo đặc tính nào trước tiên?','Layout-aware để giữ quan hệ hàng/cột và cấu trúc trang','Sentence window vì mọi bảng đều là câu văn độc lập','Fixed byte split bất kể hàng/cột bị cắt','Semantic text splitter dù parser chưa đọc được bảng','Loại dữ liệu quyết định chunking; PDF/table/scan cần layout-aware, không thể chỉ tối ưu text splitter khi layout bị mất.','apply')
mc(d,24,'BM25 cho corpus tiếng Việt cần bước chuẩn bị ngôn ngữ nào?','Word segmentation trước khi index','Chỉ bỏ mọi dấu tiếng Việt để đảm bảo term match','Chỉ embed dense rồi không cần inverted index','Dịch mọi từ thành token ngẫu nhiên trước scoring','Tiếng Việt cần phân đoạn từ để sparse keyword indexing phản ánh đơn vị từ, có thể dùng underthesea/VnCoreNLP.')
